//! Drift guard between the two canonical JSON writers: fid-canon (CORE.JRN.CANON) and the
//! kernel's own writer in fid-kci (KRN.MAN.KCI). Every string/array/object case of
//! `fixtures/man/canon-json-v1.txt` (generated by Python, see make_kci_fixtures.py) must give
//! the same bytes here. Duplicate-key cases are skipped: `CValue::Obj` cannot hold them.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_canon::{to_canonical_bytes, CValue};
use std::collections::BTreeMap;

const CASES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/man/canon-json-v1.txt");

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn utf8(hex: &str) -> String {
    String::from_utf8(unhex(hex)).unwrap()
}

/// Tokens: `{` `}` `[` `]`, `s<utf8 hex>` string value, `k<utf8 hex>` object key.
fn value(toks: &mut std::slice::Iter<'_, &str>) -> CValue {
    match *toks.next().unwrap() {
        "[" => {
            let mut items = Vec::new();
            while toks.as_slice().first() != Some(&"]") {
                items.push(value(toks));
            }
            toks.next();
            CValue::Arr(items)
        }
        "{" => {
            let mut map = BTreeMap::new();
            loop {
                let k = *toks.next().unwrap();
                if k == "}" {
                    return CValue::Obj(map);
                }
                let key = utf8(k.strip_prefix('k').unwrap());
                let v = value(toks);
                assert!(map.insert(key, v).is_none(), "duplicate key in a non-error case");
            }
        }
        s => CValue::Str(utf8(s.strip_prefix('s').unwrap())),
    }
}

#[test]
fn fid_canon_matches_kernel_canonical_json_vectors() {
    let text = std::fs::read_to_string(CASES).unwrap();
    let (mut checked, mut skipped) = (0, 0);
    for line in text.split('\n').filter(|l| !l.is_empty() && !l.starts_with('#')) {
        let f: Vec<&str> = line.split('\t').collect();
        if f[2] == "ERR duplicate_key" {
            skipped += 1;
            continue;
        }
        let toks: Vec<&str> = f[1].split(' ').collect();
        let mut it = toks.iter();
        let v = value(&mut it);
        assert!(it.next().is_none(), "{}: trailing tokens", f[0]);
        let got = to_canonical_bytes(&v).unwrap();
        assert_eq!(got, unhex(f[2]), "{}", f[0]);
        checked += 1;
    }
    assert_eq!((checked, skipped), (69, 2));
}

/// KRN.MAN.MANI.SCHEMA: the kernel manifest fixture, canonical bytes written by Python and
/// round-tripped by fid-kci's writer, is also fid-canon's canonical form, with the same
/// manifest and core digests (`fixtures/man/manifest-v1-digests.txt`).
#[test]
fn fid_canon_matches_the_kernel_manifest_fixture() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/man/");
    let bytes = std::fs::read(format!("{dir}manifest-v1.json")).unwrap();
    let digests = std::fs::read_to_string(format!("{dir}manifest-v1-digests.txt")).unwrap();
    let expected = |name: &str| {
        digests.lines().find_map(|l| l.strip_prefix(name).and_then(|r| r.strip_prefix('\t'))).unwrap().to_string()
    };
    assert_eq!(fid_canon::canonicalize(&bytes).unwrap(), bytes);
    assert_eq!(fid_canon::digest_bytes(&bytes).to_string(), expected("manifest_digest"));
    let value = fid_canon::parse(&bytes).unwrap();
    let CValue::Obj(top) = &value else { panic!("manifest is not an object") };
    let core = top.get("core").unwrap();
    assert_eq!(fid_canon::digest(core).unwrap().to_string(), expected("core_digest"));
    // A reformatted copy canonicalises to the same bytes as well.
    let pretty = std::fs::read(format!("{dir}manifest/ok-whitespace.json")).unwrap();
    assert_eq!(fid_canon::canonicalize(&pretty).unwrap(), bytes);
}
